// Small English wallet controller for the laboratory's independently pinned Devnet mode.
import {buildWalletCatalog,walletBrand} from './wallet-catalog.js';
import {DEVNET_CHAIN,DEVNET_MODULES,devnetWalletAccounts,labDevnetError} from './lab-devnet-client.js';

const moduleNames={launchpad:'Material launchpad',purchase:'Material purchase',manufacture:'Component manufacture',synthesis:'Cell, organ & organism assembly',mining:'Stake & LAB',research:'Original research',market:'Three asset markets',workLaunch:'Specimen launch'};
const noop=()=>{};
export async function mountLabDevnetWallet(host,{client,document=host?.ownerDocument,window=document?.defaultView??globalThis.window,getWallets,onStatus=noop,onConnection=noop}={}){
 if(!host||!document||!client?.subscribe)throw Error('DEVNET_WALLET_HOST');
 let registry=null,closed=false,localBusy=false,selected=null,connected=null,accounts=[],selectedAccount=null,off=null,snapshot=client.snapshot,rendering=false,generation=0;const cleanups=[];
 const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(cls)node.className=cls;return node;};
 const button=(text,fn,{disabled=false,primary=false}={})=>{const b=el('button',text,`lab-devnet-button${primary?' primary':''}`);b.type='button';b.disabled=disabled||localBusy||snapshot.busy;b.addEventListener('click',()=>{if(!b.disabled)void fn();});return b;};
 const message=el('p','Connect a wallet to read its actual Devnet SOL balance.','lab-devnet-wallet-status');message.setAttribute('role','status');
 const announce=(text,error=false)=>{if(closed)return;message.textContent=text;message.className=`lab-devnet-wallet-status${error?' error':''}`;onStatus(text,error);};
 const actual=()=>{const rows=registry?.get?.();return Array.isArray(rows)?rows:[];};
 function clearConnection(text){generation++;off?.();off=null;connected=null;accounts=[];selectedAccount=null;client.disconnect();onConnection(null);if(text)announce(text);}
 async function connect(entry){
  if(closed||localBusy||snapshot.busy)return;if(!actual().includes(entry.wallet)){announce('This wallet is no longer registered. Choose a current wallet.',true);draw();return;}
  clearConnection();selected=entry.wallet;const own=++generation;localBusy=true;draw();
  try{const result=await selected.features['standard:connect'].connect();if(closed||own!==generation||!actual().includes(entry.wallet))return;const authorized=Array.isArray(result?.accounts)?result.accounts:[];accounts=devnetWalletAccounts(entry.wallet).filter(a=>authorized.some(r=>r.address===a.address&&r.publicKey instanceof Uint8Array&&r.publicKey.length===a.publicKey.length&&r.publicKey.every((v,i)=>v===a.publicKey[i])));if(!accounts.length)throw Object.assign(Error('DEVNET_ACCOUNT'),{code:'DEVNET_ACCOUNT'});connected=entry.wallet;selectedAccount=accounts[0];
    if(typeof connected.features?.['standard:events']?.on==='function')off=connected.features['standard:events'].on('change',()=>{if(closed)return;clearConnection('Wallet accounts changed. Reconnect before using Devnet.');draw();});
    await client.setWallet(connected,selectedAccount);if(closed||own!==generation)return;announce('Wallet connected to Devnet. Connecting alone does not sign or send a transaction.');onConnection({wallet:connected,account:selectedAccount});
  }catch(e){if(!closed&&own===generation){clearConnection();announce(labDevnetError(e),true);}}
  finally{if(!closed){localBusy=false;draw();}}
 }
 async function chooseAccount(index){const account=accounts[index];if(!account||!connected)return;generation++;selectedAccount=account;await client.setWallet(connected,account);announce('The selected account was refreshed. Previous account requests remain isolated.');onConnection({wallet:connected,account});draw();}
 async function disconnect(){const wallet=connected;clearConnection('Wallet disconnected. Pending transactions remain in their original request journals.');try{await wallet?.features?.['standard:disconnect']?.disconnect?.();}catch{}draw();}
 function draw(){
  if(closed||rendering)return;rendering=true;try{host.replaceChildren();host.className=[...new Set([...String(host.className??'').split(/\s+/).filter(Boolean),'lab-devnet-wallet'])].join(' ');const header=el('div',undefined,'lab-devnet-heading');header.append(el('p','SOLANA DEVNET','lab-devnet-eyebrow'),el('h3','Your test-network wallet'));host.append(header);
   const cfg=snapshot.config;host.append(el('p',cfg?.deployment.status==='READY'?'The deployed Devnet program is selected. Every transaction still needs your wallet approval.':cfg?'The Devnet connection is selected. The program is not deployed or is blocked; business actions remain unavailable.':'Verifying the Devnet network. Wallet actions remain locked.','lab-devnet-note'));
   const rows=buildWalletCatalog(actual(),{known:cfg!==null,chain:DEVNET_CHAIN},selected);const cards=el('div',undefined,'lab-devnet-wallet-list');
   for(const entry of rows){const card=el('article',undefined,'lab-devnet-wallet-card'),name=entry.wallet?walletBrand(entry.wallet).name:entry.key==='phantom'?'Phantom':entry.name;card.append(el('h4',name));if(entry.installed){const available=typeof entry.wallet?.features?.['standard:connect']?.connect==='function'&&Array.isArray(entry.wallet.chains)&&entry.wallet.chains.includes(DEVNET_CHAIN);card.append(el('p',!available?'Devnet connection is not declared.':entry.capabilities.transactionSupported?'Devnet connection and numeric v1 signing declared.':'Devnet balance reads available. Numeric v1 transaction support is missing.','lab-devnet-note'));card.append(button(connected===entry.wallet?'Reconnect wallet':`Connect ${name}`,()=>connect(entry),{primary:connected===entry.wallet,disabled:!cfg||!available}));}else{card.append(el('p','Not detected in this browser.','lab-devnet-note'));const link=el('a','Official wallet download','lab-devnet-link');link.href=entry.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);}cards.append(card);}host.append(cards);
   if(connected&&selectedAccount){const identity=el('div',undefined,'lab-devnet-account');identity.append(el('strong',`${walletBrand(connected).name} connected`));if(accounts.length>1){const label=el('label','Wallet account'),select=el('select');select.setAttribute('aria-label','Devnet wallet account');select.disabled=localBusy||snapshot.busy;for(const [i,a]of accounts.entries()){const option=el('option',a.address);option.value=String(i);select.append(option);}select.value=String(accounts.indexOf(selectedAccount));select.addEventListener('change',()=>void chooseAccount(Number(select.value)));label.append(select);identity.append(label);}else identity.append(el('code',selectedAccount.address));
    const w=snapshot.state?.wallet;identity.append(el('p',w?`${formatUnits(w.solLamports,9)} test SOL · ${w.labAtoms===null?'LAB balance unavailable':`${formatUnits(w.labAtoms,6)} test LAB`}`:'Reading actual Devnet balances…','lab-devnet-balances'));const controls=el('div',undefined,'lab-devnet-actions');controls.append(button('Refresh balances',()=>client.refresh()),button('Disconnect',disconnect));if(cfg?.deployment.status==='READY'&&cfg.nativeConfig?.authenticationRequired===true)controls.append(snapshot.authenticated?button('Sign out',()=>client.logout()):button('Sign in to Devnet',()=>client.login(),{primary:true,disabled:typeof connected.features?.['solana:signMessage']?.signMessage!=='function'}));identity.append(controls);host.append(identity);
   }
   if(snapshot.pending){const recovery=el('section',undefined,'lab-devnet-recovery');recovery.append(el('h4','Resume the original transaction'),el('p',`${snapshot.pending.operation} · ${snapshot.pending.stage.replaceAll('_',' ').toLowerCase()}. Your request stays bound to this wallet and deployment.`),button('Resume pending transaction',()=>client.resume?client.resume():client.recover(),{primary:true,disabled:!snapshot.connected||cfg?.deployment.status!=='READY'}));host.append(recovery);}
   if(snapshot.otherPendingCount)host.append(el('p',`${snapshot.otherPendingCount} request record(s) belong to another wallet or deployment. They are preserved separately.`,'lab-devnet-note'));
   const modules=el('details',undefined,'lab-devnet-capabilities'),summary=el('summary','Devnet module availability');modules.append(summary);for(const key of DEVNET_MODULES){const capability=cfg?.capabilities[key];modules.append(el('p',`${moduleNames[key]} — ${capability?.available?'available':'not ready'}${capability?.reason?`: ${capability.reason}`:''}`));}host.append(modules,message);
  }finally{rendering=false;}
 }
 function refreshRegistry(){if(closed)return;if(connected&&!actual().includes(connected)){clearConnection('The connected wallet left this browser. Reconnect to continue.');}draw();}
 const unsubscribe=client.subscribe(next=>{snapshot=next;draw();});cleanups.push(unsubscribe);
 try{registry=(getWallets??(await import('/vendor/wallets.js')).getWallets)();for(const name of ['register','unregister']){const remove=registry.on(name,refreshRegistry);if(typeof remove==='function')cleanups.push(remove);}}catch{announce('Wallet discovery is unavailable. Install a supported wallet in this browser and refresh.',true);}
 draw();return{draw,get snapshot(){return{connected:connected!==null,account:selectedAccount?.address??null};},close(){if(closed)return;closed=true;generation++;off?.();for(const fn of cleanups)fn();}};
}
export function formatUnits(value,decimals){if(typeof value!=='string'||!/^(?:0|[1-9][0-9]*)$/.test(value)||!Number.isInteger(decimals)||decimals<0||decimals>9)return '—';const base=10n**BigInt(decimals),n=BigInt(value),tail=(n%base).toString().padStart(decimals,'0').replace(/0+$/,'');return`${n/base}${tail?'.'+tail:''}`;}
